// Aggregate estimatedTotalAmount per lineItem from a PR items array.
const _aggregateTotals = (items) =>
  (items || []).reduce((map, item) => {
    if (!item.lineItem) return map;
    const id = String(item.lineItem._id !== undefined ? item.lineItem._id : item.lineItem);
    map[id] = (map[id] || 0) + (item.estimatedTotalAmount || 0);
    return map;
  }, {});

/**
 * Reserve budget at the line-item level on PR submission.
 *
 * For each PR line item, checks that LineItem.availableAmount covers the
 * estimated total. On success, reduces availableAmount and creates an active
 * BudgetReservation record. On any insufficiency, throws an ApiError with a
 * `detail` object identifying the breaching line item and rolls back all
 * changes made in the call via session transaction.
 */
const reserveBudget = async (prId, prNumber, lineItems) => {
  const lineItemTotals = _aggregateTotals(lineItems);

  const session = await mongoose.startSession();
  try {
    await session.withTransaction(async () => {
      for (const [lineItemId, amount] of Object.entries(lineItemTotals)) {
        const li = await LineItem.findById(Number(lineItemId)).session(session);
        if (!li) {
          throw new ApiError(httpStatus.NOT_FOUND, `Line item ${lineItemId} not found`);
        }

        if ((li.availableAmount || 0) < amount) {
          const err = new ApiError(
            httpStatus.UNPROCESSABLE_ENTITY,
            `Insufficient budget: "${li.name}" has ${li.availableAmount} available, ${amount} required`
          );
          err.detail = {
            lineItemId: li._id,
            lineItemName: li.name,
            available: li.availableAmount,
            required: amount,
          };
          throw err;
        }

